        private void cboComboCardNumber_SelectedIndexChanged(object sender, EventArgs e)
        {
            Int16 Number;
            UInt16 card_num = (UInt16)cboComboCardNumber.SelectedIndex;
            //(U16)((CComboBox*)GetDlgItem(IDC_COMBO_CARD_NUMBER))->GetCurSel();


            if (m_Number >= 0)
                SmartPoE.SmartPoE_Release_Card((ushort)m_Number);

            if ((Number = SmartPoE.SmartPoE_Register_Card(card_num)) != SmartPoE.PoE_NoError)
            {
                MessageBox.Show("Selecting card is failed");
                return;
            }

            ushort ID;
            short EEVersion, EEStandard, EEPort;
            ushort MCUVersion;
            Int16 ret = SmartPoE.SmartPoE_Get_ID((ushort)Number, out ID);
            if (ret < 0)
                txtEditError.Text = "Error";
            else
                txtEditId.Text = ID.ToString();


            m_Number = Number;

            /////////////////////////////

            ret = SmartPoE.GIE_Get_Chk_EEVersion((ushort)Number, out EEVersion);
            if (ret < 0)
                txtEditError.Text = "Error";
            else
                txtEditId14.Text = EEVersion.ToString();


            ret = SmartPoE.GIE_Get_Chk_EEStandard((ushort)Number, out EEStandard);
            if (ret < 0)
                txtEditError.Text = "Error";
            else
                txtEditId15.Text = EEStandard.ToString();

            ret = SmartPoE.GIE_Get_Chk_EEPort((UInt16)Number, out EEPort);
            if (ret < 0)
                txtEditError.Text = "Error";
            else
                txtEditId16.Text = EEPort.ToString();

            UInt32 ID2, ID3;
            ret = SmartPoE.SmartPoE_Get_CPLDVersion((UInt16)Number, out ID2, out ID3);
            if (ret < 0)
                txtEditError.Text = "Error";
            else
            {
                txtEditId18.Text = String.Format("{0:x}", ID2);
                txtEditId19.Text = String.Format("{0:x}", ID3);
            }

            ret = SmartPoE.SmartPoE_Get_MCUVersion((UInt16)Number, out MCUVersion);
            if (ret < 0)
                txtEditId20.Text = "Error";
            else
                txtEditId20.Text = Convert.ToString(MCUVersion, 16);


            /////////////////////////////

        }

