        private uint hex2uint(string h)
        {
            int len;
            string str;
            uint ret = 0;
            sbyte c;

            len = h.Length;
            if (len > 16 || len <= 0)
            {
                return 0;
            }

            h.ToUpper();
            //str = h.GetBuffer(10); 
            str = h;

            for (int i = 0; i < len; i++)
            {
                c = (sbyte)str[i];
                if (c >= '0' && c <= '9')
                {
                    ret = (uint) ((ret << 4) + c - '0');
                }
                else if (c >= 'A' && c <= 'F')
                {
                    ret = (uint)((ret << 4) + c - 'A' + 10);
                }
                else
                {
                    return 0;
                }
            }

            return ret;
        }

